import{_ as n,a0 as r,w as p,s as o,I as t,x as a,a1 as e,A as s,ao as u}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const g=JSON.parse('{"title":"Kali Linux 是什麼，你需要它嗎？ | LCTT x X-CMD","titleTemplate":false,"description":"Kali Linux 是什麼，你需要它嗎？ | LCTT (201802) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Kali Linux 是什麼，你需要它嗎？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Kali Linux 是什麼，你需要它嗎？ | LCTT (201802) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201802/20180206 What Is Kali Linux, and Do You Need It","title":"Kali Linux 是什麼，你需要它嗎？","tag":"201802","desc":""},"relativePath":"201802/20180206 What Is Kali Linux, and Do You Need It.md","filePath":"[post].md"}'),d={name:"201802/20180206 What Is Kali Linux, and Do You Need It.md"};function m(x,i,K,w,k,f){const l=r("Link");return p(),o("div",null,[i[20]||(i[20]=t("h1",{id:"kali-linux-是什麼-你需要它嗎",tabindex:"-1"},[a("Kali Linux 是什麼，你需要它嗎？ "),t("a",{class:"header-anchor",href:"#kali-linux-是什麼-你需要它嗎","aria-label":"Permalink to “Kali Linux 是什麼，你需要它嗎？”"},"​")],-1)),i[21]||(i[21]=t("p",null,[t("img",{src:"https://www.maketecheasier.com/assets/uploads/2018/01/kl-feat.jpg",alt:""})],-1)),i[22]||(i[22]=t("p",null,"如果你聽到一個 13 歲的黑客吹噓他是多麼的牛逼，是有可能的，因為有 Kali Linux 的存在。儘管有可能會被稱為“腳本小子”，但是事實上，Kali 仍舊是安全專家手頭的重要工具（或工具集）。",-1)),i[23]||(i[23]=t("p",null,"Kali 是一個基於 Debian 的 Linux 發行版。它的目標就是為了簡單：在一個實用的工具包裏儘可能多的包含滲透和審計工具。Kali 實現了這個目標。大多數做安全測試的開源工具都被囊括在內。",-1)),t("p",null,[i[1]||(i[1]=t("strong",null,"相關",-1)),i[2]||(i[2]=a(" ： ",-1)),e(l,{href:"https://www.maketecheasier.com/linux-distros-designed-for-privacy-security/",title:"4 Great Linux Distros Designed for Privacy and Security"},{default:s(()=>[...i[0]||(i[0]=[a("4 個極好的為隱私和安全設計的 Linux 發行版",-1)])]),_:1})]),i[24]||(i[24]=t("h3",{id:"為什麼是-kali",tabindex:"-1"},[a("為什麼是 Kali？ "),t("a",{class:"header-anchor",href:"#為什麼是-kali","aria-label":"Permalink to “為什麼是 Kali？”"},"​")],-1)),i[25]||(i[25]=t("p",null,[t("img",{src:"https://www.maketecheasier.com/assets/uploads/2018/01/kl-desktop.jpg",alt:"Kali Linux Desktop",title:"Kali Linux Desktop"})],-1)),t("p",null,[e(l,{href:"https://www.offensive-security.com/kali-linux-vmware-virtualbox-image-download/"},{default:s(()=>[...i[3]||(i[3]=[a("Kali",-1)])]),_:1}),i[5]||(i[5]=a(" 是由 ",-1)),e(l,{href:"https://www.offensive-security.com/"},{default:s(()=>[...i[4]||(i[4]=[a("Offensive Security",-1)])]),_:1}),i[6]||(i[6]=a(" 公司開發和維護的。它在安全領域是一家知名的、值得信賴的公司，它甚至還有一些受人尊敬的認證，來對安全從業人員做資格認證。",-1))]),i[26]||(i[26]=u('<p>Kali 也是一個簡便的安全解決方案。Kali 並不要求你自己去維護一個 Linux 系統，或者你自己去收集軟件和依賴項。它是一個“交鑰匙工程”。所有這些繁雜的工作都不需要你去考慮，因此，你只需要專注於要審計的真實工作上，而不需要去考慮準備測試系統。</p><h3 id="如何使用它" tabindex="-1">如何使用它？ <a class="header-anchor" href="#如何使用它" aria-label="Permalink to “如何使用它？”">​</a></h3><p>Kali 是一個 Linux 發行版。與任何一個其它的 Linux 發行版一樣，你可以將它永久安裝到一個硬盤上。那樣它會工作的更好，但是你不能將它作為一個日常使用的操作系統。因為它是為滲透測試構建的，這就是你使用它的全部理由。</p><p>最好是將 Kali 製作為自啓動發行版。你可以將 Kali 刻錄到一張 DVD 或者是製作到一個自啓動 U 盤上來運行它。你沒有必要在一個 Kali 上安裝任何軟件或者保存任何文件。你可以在需要測試一個系統時隨時來啓動它。它也有非常好的靈活性，可以讓運行 Kali 的機器隨時運行在想要測試的網絡上。</p><h3 id="kali-可以做什麼" tabindex="-1">Kali 可以做什麼？ <a class="header-anchor" href="#kali-可以做什麼" aria-label="Permalink to “Kali 可以做什麼？”">​</a></h3><p>Kali 裏面有很多的安全工具而不是別的。這就是它能做的事。不管怎麼説，Kali 就是一個安全工具。</p><p><img src="https://www.maketecheasier.com/assets/uploads/2018/01/kl-zenmap.jpg" alt="Kali Zenmap" title="Kali Zenmap"></p><p>它有像 NMap 和 Wireskark 這樣的經典信息採集工具。</p><p><img src="https://www.maketecheasier.com/assets/uploads/2018/01/kl-wireshark.jpg" alt="Kali Linux Wireshark" title="Kali Linux Wireshark"></p><p>Kali 也有面向 WiFi 的工具，像 Aircrack-ng、Kismet、以及 Pixie。</p><p>對於破解密碼，它也有像 Hydra、Crunch、Hashcat、以及 John the Ripper 這樣的工具。</p><p><img src="https://www.maketecheasier.com/assets/uploads/2018/01/kl-metasploit.jpg" alt="Kali Metasploit" title="Kali Metasploit"></p><p>還有更多的成套工具，包括 Metasploit 和 Burp Suite。</p><p>這些只是 Kali 缺省內置的一小部分安全工具。完整的瞭解這些工具需要很多的時間，但是，你可以清楚地看到許多非常流行的工具它都有。</p><h3 id="kali-是為你準備的嗎" tabindex="-1">Kali 是為你準備的嗎？ <a class="header-anchor" href="#kali-是為你準備的嗎" aria-label="Permalink to “Kali 是為你準備的嗎？”">​</a></h3><p>Kali 並不是為普通用户準備的。它並不是一個運行在你的筆記本電腦上的普通 Linux 發行版，而是一個很酷的“黑客操作系統“。如果你使用這個操作系統，那麼你將會運行着一個缺乏安全保障的系統，因為 Kali 被設計為以 root 權限運行。它自身並不安全，並且它的配置也與普通的 Linux 發行版不一樣。它是一個攻擊型工具，而不是一個防禦型工具。</p><p>Kali 並不是個玩具。你可以使用它內置的工具去做一些會產生真實傷害的危險的事（你懂的），那將給你帶來很多真實的麻煩。對於一個未受到嚴格教育的用户來説，做一些嚴重違法的事情是很容易的，並且之後你就會發現自己被陷入很無助的境地。</p><p>説了這麼多，但是，Kali 對於一個專業用户來説，它是一個極好的工具。如果你是一個網絡管理員，想對你的網絡做一個真實的測試，Kali 可以做到你所希望的一切事情。Kali 也有一些優秀的開發工具，用於去實時審計它們的應用程序。</p><p>當然，如果你正好有興趣學習關於安全的知識，你可以在某些受控環境中去使用 Kali，它可以教你學習很多的非常優秀的知識。</p><p>Kali Linux 是許多優秀的安全工具的集合。對於專業用户來説，它有難以置信的好處，但是對於一些不懷好意的人來説，也可以產生很多大麻煩。小心地使用 Kali，充分利用它的巨大優勢。如果不這樣的話，你將在某個地方（你懂的）度過你的餘生。</p><hr>',21)),t("p",null,[i[8]||(i[8]=a("via: ",-1)),e(l,{href:"https://www.maketecheasier.com/what-is-kali-linux-and-do-you-need-it/"},{default:s(()=>[...i[7]||(i[7]=[a("https://www.maketecheasier.com/what-is-kali-linux-and-do-you-need-it/",-1)])]),_:1})]),t("p",null,[i[12]||(i[12]=a("作者：",-1)),e(l,{href:"https://www.maketecheasier.com/author/nickcongleton/"},{default:s(()=>[...i[9]||(i[9]=[a("Nick Congleton",-1)])]),_:1}),i[13]||(i[13]=a(" 譯者：",-1)),e(l,{href:"https://github.com/qhwdw"},{default:s(()=>[...i[10]||(i[10]=[a("qhwdw",-1)])]),_:1}),i[14]||(i[14]=a(" 校對：",-1)),e(l,{href:"https://github.com/wxy"},{default:s(()=>[...i[11]||(i[11]=[a("wxy",-1)])]),_:1})]),t("p",null,[i[17]||(i[17]=a("本文由 ",-1)),e(l,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...i[15]||(i[15]=[a("LCTT",-1)])]),_:1}),i[18]||(i[18]=a(" 原創編譯，",-1)),e(l,{href:"https://linux.cn/"},{default:s(()=>[...i[16]||(i[16]=[a("Linux中國",-1)])]),_:1}),i[19]||(i[19]=a(" 榮譽推出",-1))])])}const T=n(d,[["render",m]]);export{g as __pageData,T as default};
